-- ---------------------------------------------------------------- B3 store box
function PTHT_Box()
	local m = PTHT_MapOk()
	if not m then
		PTHT_Blocked()
		return
	end
	if GetFightState() == 1 then
		-- KItemList::ExchangeItem refuses to put items into a box page in fight mode
		SetTask(PTHT_T_FIGHT, m)
		SetFightState(0)
		Msg2Player("\167\183 t\185m t\190t tr\185ng th\184i chi\213n \174\202u \174\211 c\202t \174\229 v\181o r\173\172ng. C\202t xong ch\228n \\\"B\203t l\185i tr\185ng th\184i chi\213n \174\202u\\\" tr\170n l\214nh b\181i; n\213u qu\170n, kho\182ng 3 ph\243t sau s\207 t\249 b\203t l\185i.")
	end
	Msg2Player("R\173\172ng ch\248a \174\229: b\202m m\242i t\170n ph\182i trong khung r\173\172ng \174\211 sang R\173\172ng 2 - 5 (m\235 th\170m r\173\172ng \235 Th\241 Kh\232).")
	OpenBox(2)
end

function PTHT_Fight()
	local m = GetTask(PTHT_T_FIGHT)
	SetTask(PTHT_T_FIGHT, 0)
	if m > 0 and GetWorldPos() == m and GetFightState() == 0 then
		SetFightState(1)
		Msg2Player("\167\183 b\203t l\185i tr\185ng th\184i chi\213n \174\202u.")
	else
		Msg2Player("Kh\171ng c\199n b\203t l\185i tr\185ng th\184i chi\213n \174\202u (\174\183 b\203t ho\198c \174\183 \174\230i b\182n \174\229).")
	end
end

