-- ---------------------------------------------------------------- B2 clean bag
function PTHT_Clean()
	if not PTItemSaleInfo then
		Say("D\228n t\243i c\199n b\182n CoreServer.dll m\237i (h\181m PTItemSaleInfo, \174\238t H\181nh Trang). B\184o admin c\181i b\182n server m\237i; trong l\243c ch\234 c\227 th\211 b\184n \235 c\246a h\181ng ho\198c L\214nh B\181i H\241y \167\229.", 1, "\167\227ng/PTHT_No")
		return
	end
	if not PTHT_MapOk() then
		PTHT_Blocked()
		return
	end
	local nm = GetName()
	local L = PTHT_Scan()
	if L.n == 0 then
		PTHT_PEND[nm] = nil
		Say("Kh\171ng c\227 m\227n n\181o kh\237p b\233 l\228c d\228n t\243i (" .. PTHT_SellDesc() .. "). Kh\171ng bao gi\234 b\184n: \174\229 \174ang m\198c, \174\229 kh\227a, \174\229 nhi\214m v\244, b\221 k\221p, ph\184p b\182o, l\214nh b\181i, nguy\170n li\214u, \174\184 qu\253, \174\229 ho\181ng kim.", 2, "C\181i \174\198t d\228n t\243i/PTHT_S", "\167\227ng/PTHT_No")
		return
	end
	PTHT_PEND[nm] = L
	Msg2Player("D\228n t\243i - danh s\184ch s\207 b\184n (" .. L.n .. " m\227n):")
	local i = 1
	while i <= L.n do
		Msg2Player(i .. ". " .. L[i].nm .. " - " .. L[i].money .. " l\173\238ng")
		i = i + 1
	end
	Say("S\207 b\184n <color=yellow>" .. L.n .. " m\227n<color>, thu " .. L.total .. " l\173\238ng (gi\184 c\246a h\181ng). Danh s\184ch t\245ng m\227n \235 khung chat. \167\229ng \253 b\184n?", 3, "\167\229ng \253 b\184n " .. L.n .. " m\227n/PTHT_CleanOK", "C\181i \174\198t d\228n t\243i/PTHT_S", "H\241y/PTHT_No")
end

function PTHT_CleanOK()
	local nm = GetName()
	local L = PTHT_PEND[nm]
	PTHT_PEND[nm] = nil
	if not L then
		Msg2Player("Danh s\184ch d\228n t\243i \174\183 h\213t h\185n, h\183y ch\228n D\228n t\243i l\185i.")
		return
	end
	local n, tot = PTHT_Sell(L, "tay")
	Msg2Player("D\228n t\243i: \174\183 b\184n " .. n .. "/" .. L.n .. " m\227n, thu " .. tot .. " l\173\238ng. Nh\203t k\253 xem \235 web admin (H\181nh Trang).")
end

